"""Individual model narratives; no operating instructions or invented dates."""
CURATED = {}

def add(id, *paragraphs, country=None, sections=None, evidence=None):
    CURATED[id] = dict(paragraphs=paragraphs, country=country, sections=sections or {}, evidence=evidence or [])

add('mine-audit-v25-de-sm-70',
    'SM-70 — восточногерманская противопехотная осколочная мина направленного действия. Её история связана с пограничными заграждениями ГДР на границе с ФРГ. В отличие от привычных круглых мин, SM-70 имела воронкообразный корпус: необычная форма была частью конструкции направленного боеприпаса.',
    'Название раскрывается как Splittermine Modell 1970 — «осколочная мина образца 1970 года». Изготовителем было государственное предприятие VEB Chemiewerk Kapen. Эти изделия стали одним из символов технического оснащения внутренней германской границы во время холодной войны; на Берлинской стене SM-70 не применялись.',
    '5 октября 1983 года Эрих Хонеккер объявил об отказе от таких заграждений. Последние SM-70 демонтировали в ноябре 1984 года — ещё до падения Берлинской стены и объединения Германии. Поэтому история модели относится к конкретному этапу существования границы, а не ко всему периоду разделения страны.',
    country='ГДР; исторический изготовитель — VEB Chemiewerk Kapen',
    evidence=[{'url':'https://www.bundesarchiv.de/themen-entdecken/online-entdecken/themenbeitraege/der-veb-chemiewerk-kapen-und-die-splittermine-sm-70/', 'claims':'Обозначение, изготовитель, форма корпуса, внутренняя германская граница, отсутствие на Берлинской стене, даты объявления и окончания демонтажа.'}])
add('mine-audit-v25-ru-ptkm-1r',
    'ПТКМ-1Р — российская противотанковая мина с отдельным боевым элементом, предназначенным для воздействия на верхнюю часть бронетехники. По общей конструкции она сильно отличается от плоских дисковых мин: основную внешнюю часть изделия составляет высокий транспортно-пусковой контейнер.',
    'В составе ПТКМ-1Р различают контейнер и боевой элемент. Это объясняет необычные для мины пропорции и сравнительно большую полную массу — 19,9 кг. Характеристики всего изделия и его отдельной части относятся к разным объектам, хотя в кратких перечнях они нередко стоят рядом.',
    'Высота изделия составляет 510 мм, а диаметр корпуса боевого элемента — 220 мм. Таким образом, краткую запись «510×220» следует читать с учётом этих двух разных определений, а не как длину и ширину плоского корпуса. Модель относится к современной российской номенклатуре инженерных боеприпасов.',
    evidence=[{'url':'https://roe.ru/production/land-forces/engineer-equipment/ptkm-1r/?theme=theme-green','claims':'Общий класс; контейнер и боевой элемент как две части; полная масса, высота изделия и диаметр корпуса боевого элемента. Порядок действия не переносился.'}])
add('mine-audit-v25-su-tm-73',
    'ТМ-73 — советский противотанковый минный комплект противобортового типа. Его название может создавать впечатление обычной мины с отдельным круглым корпусом, однако здесь речь идёт о комплекте, в состав которого входит противотанковая граната РПГ-18. Именно состав изделия объясняет его отличие от дисковых ТМ-57 и ТМ-62.',
    'ТМ-73 относится к номенклатуре периода холодной войны. Внешний облик комплекта определяется его отдельными частями, поэтому изображение одного компонента не показывает весь предмет, обозначаемый этим индексом. Это особенно существенно для справочных фотографий, на которых трубчатый компонент может занимать почти весь кадр.',
    'Полная масса комплекта около 8 кг и масса гранаты РПГ-18 около 2,6 кг — разные характеристики. Ниже они сохранены отдельно: меньшая величина описывает компонент, а не облегчённое исполнение всей ТМ-73.')
add('eng-pom-2-family',
    'ПОМ-2 — семейство советских противопехотных осколочных мин с узким цилиндрическим корпусом. Внешний облик особенно заметно меняют шесть наружных опор: компактный цилиндр и изделие с раскрытыми опорами выглядят совершенно по-разному, хотя относятся к одной линии моделей.',
    'У описанного ПОМ-2С стальной корпус, ажурные опоры и чёрные обозначения по окружности. Известны светло-коричневые и оливково-зелёные образцы. От низких дисков ПМН эта группа отличается вытянутыми пропорциями и выступающими деталями. Диаметр 58 мм в отдельной записи ПОМ-2С не подтверждает полный размах опор.',
    'ПОМ-2 и ПОМ-2С представлены раздельными наборами характеристик. Для ПОМ-2С приводится полная масса 1,06 кг, а для другой записи ПОМ-2 — 1,6 кг. Это не диапазон массы одной условной мины: различие обозначений и комплектации необходимо сохранять и при сравнении фотографий, и при чтении размеров.')
add('mine-audit-v25-su-pom-1s',
    'ПОМ-1 и ПОМ-1С — советские противопехотные осколочные мины с округлым, почти шарообразным корпусом. Такой силуэт выделяет их среди цилиндрических ПОМ-2 и плоских мин ПМН. Общие буквы ПОМ объединяют класс и номенклатуру, но не задают единую форму корпуса.',
    'В этой паре суффикс «С» обозначает отдельное исполнение. Внешняя близость двух вариантов не превращает ПОМ-1 и ПОМ-1С в два равнозначных написания одной модели; различия относятся к внутреннему устройству, а не обязательно к хорошо заметным наружным деталям.',
    'Для ПОМ-1С указана полная масса 750 г. Размерная запись 80×80 мм описывает компактный округлый предмет, однако направление каждой оси в ней отдельно не раскрыто. Эти значения относятся к данной записи ПОМ-1С и не заменяют характеристики других представителей семейства ПОМ.')
add('mine-audit-v25-su-pom-2s',
    'ПОМ-2С — советская противопехотная осколочная мина из семейства ПОМ-2. Её корпус узкий и цилиндрический, с наружными опорами, которые придают изделию характерный ажурный силуэт. По форме она значительно ближе к другим ПОМ-2, чем к шарообразной ПОМ-1С.',
    'Обозначение ПОМ-2С следует сохранять целиком: суффикс выделяет конкретное исполнение внутри семейства. На изображениях опоры могут занимать больше места, чем сам корпус, поэтому впечатление о размере всего предмета зависит от показанной наружной комплектации.',
    'В одной размерной записи приведены 18×6,3 см, то есть 180×63 мм. Это не подтверждённый размер полного размаха опор. Отдельно указанная масса взрывчатого содержимого 120 г также не является полной массой мины: корпус и остальные части в эту величину не входят.')
add('ref-v8-pom-3',
    'ПОМ-3, известная также как «Медальон», — российская противопехотная осколочная мина, продолжающая линию ПОМ-2. Она была публично представлена в 2015 году, а первые поставки российским вооружённым силам относятся к началу 2019 года. Между появлением модели на выставках и её поступлением в войска прошло несколько лет.',
    'От предшественников ПОМ-3 отличается применением сейсмического датчика и электронной системы обработки сигналов. Эти особенности относятся к общей конструкции модели. Популярные утверждения о способности безошибочно различать военнослужащих и гражданских не получили независимого подтверждения.',
    'Внешне основную часть изделия составляет вытянутый цилиндрический корпус. Опубликованные размерные записи расходятся: встречаются высота 200 мм и диаметр 60–70 мм, а также габариты 183×60 мм. Полная масса приводится как 1,3 кг либо 1,2 кг. Ниже сохранены оба набора, без объединения их в паспорт единого исполнения.',
    evidence=[{'url':'https://armamentresearch.com/russian-pom-3-anti-personnel-landmines-documented-in-ukraine-2022/','claims':'Публичное представление 2015 года, начало поставок 2019 года, связь с ПОМ-2, общий тип датчика, отсутствие независимого подтверждения заявлений о распознавании людей. Алгоритмы, последовательность действия и дистанции исключены.'}])
add('eng-m18a1',
    'M18A1 Claymore — американская противопехотная осколочная мина направленного действия. Её характерный корпус выглядит как широкий изогнутый прямоугольник на тонких складных опорах. Этот силуэт заметно отличается и от круглых мин, и от высоких металлических цилиндров семейства M16.',
    'На зелёных образцах встречаются выпуклые англоязычные надписи. Изгиб широких поверхностей — особенность самого корпуса, а видимая высота зависит ещё и от положения опор. Поэтому фотография с разложенными ножками показывает иные наружные пропорции, чем изображение компактного изделия.',
    'Справочная ширина корпуса составляет 216 мм, толщина — 35 мм, высота со сложенными опорами — 82 мм; полная масса — 1,59 кг. Южнокорейская KM18A1 имеет собственное обозначение и отдельные учебные исполнения. Её характеристики не следует смешивать с данными американской M18A1.',
    country='США; M18A1 Claymore')
add('eng-m19',
    'M19 — американская противотанковая мина, узнаваемая по широкому квадратному корпусу со скруглёнными углами. На плоской верхней части выделяется круглая центральная область. Такая геометрия делает M19 заметным исключением среди многих противотанковых мин с дисковым корпусом.',
    'На справочных фотографиях встречается зеленовато-серое исполнение. История модели связана не только с США: производство родственных изделий во второй половине XX века отмечено также в Иране, Республике Корея, Чили и Турции. Эта география описывает историю выпуска, а не состав современных арсеналов.',
    'M19 — крупное и тяжёлое изделие: её полная масса около 12,5 кг. В размерной записи со взрывателем высота составляет около 94 мм, а ширина — около 332 мм. Невысокий профиль и большой квадратный план помогают понять общие пропорции корпуса лучше, чем одно значение массы.')
add('eng-m14-ap-mine',
    'M14 — американская противопехотная мина с небольшим круглым пластиковым корпусом. Она принадлежит к группе низких компактных мин и по внешним пропорциям резко отличается от американских металлических M16. В описании M14 важнее всего небольшая высота и простая дискообразная форма.',
    'Размеры корпуса находятся примерно в пределах шести сантиметров по ширине и четырёх по высоте. В разных справочных записях численные значения немного отличаются; отдельные записи массы расходятся сильнее, причём одна исходная пара унций и граммов содержит ошибку пересчёта. Ниже эти расхождения обозначены прямо.',
    'Южнокорейская KM14 связана с этой конструкцией, однако её учебный корпус имеет собственные размеры и массу. Учебный аналог может воспроизводить форму боевой модели, не повторяя её внутреннее содержимое и полную массу. Поэтому данные KM14 не заменяют самостоятельные характеристики M14.')
add('eng-m16-mine-family',
    'M16, M16A1 и M16A2 — семейство американских противопехотных осколочных мин с металлическим цилиндрическим корпусом. Внешне это сравнительно высокие изделия с выраженными концентрическими деталями в верхней части и выступающим взрывателем. Они мало похожи на плоские пластиковые M14.',
    'Основные обозначения относятся к разным модификациям. M16A2 легче ранних M16 и M16A1: в одном наборе характеристик приведены 2,83 кг против 3,57 кг. Для комплектных изделий военные таблицы дают другие значения массы, поэтому два набора сохранены раздельно.',
    'Высота одного корпуса и высота мины с выступающими деталями также различаются. На фотографиях встречаются M16A1 зарубежного изготовления, в том числе греческие, индийские и южнокорейские экземпляры. Лицензионная история объясняет разнообразие маркировки, но не отменяет различий между A1 и A2.')
add('eng-m15-av',
    'M15 — американская противотанковая мина с широким низким металлическим корпусом круглой формы. Она пришла на смену M6A2 в американской номенклатуре. Сходный дисковый силуэт скрывает существенное различие массы: M15 заметно тяжелее предшественницы.',
    'Полная масса M15 составляет около 14,3 кг, диаметр — 333 мм, высота — 125 мм. Корпус выглядит широким относительно своей высоты; сверху выделяется центральная область. Такие пропорции характерны для этой модели, а не для всех американских противотанковых мин.',
    'Название M15 встречается в исторических описаниях боеприпасов разных стран. Распространение модели и её происхождение — разные сведения: исходная американская конструкция могла появляться далеко за пределами США. Отдельные зарубежные исполнения требуют собственного подтверждения характеристик.')
add('eng-m21-av',
    'M21 — американская противотанковая мина с круглым металлическим корпусом и гибким боковым ремнём. По общему силуэту она принадлежит к группе невысоких цилиндрических изделий, однако меньше и легче M15: в одной записи полная масса M21 составляет 7,8 кг.',
    'У описанного зелёного экземпляра хорошо заметны центральная область верхней поверхности и светлые надписи. Ремень сбоку является частью внешнего облика показанного корпуса. Фотографии с разной наружной комплектацией могут создавать разное впечатление о высоте изделия.',
    'Высота корпуса 11,5 см и высота со взрывателем около 206 мм описывают разные габариты. Аналогично, округлённые 7,8 кг и 17,5 фунта в другом наборе характеристик оставлены раздельно. M21 имеет собственный паспорт; номер модели не означает размер или массу.',
    country='США')
add('eng-m6a2-av',
    'M6A2 — американская противотанковая мина семейства M6 с наружной оболочкой из листового металла. Её широкий низкий корпус напоминает диск: сверху выделяются приподнятая круглая площадка и центральная область. На описанном экземпляре сохранена оливковая окраска.',
    'История M6A2 связана с послевоенными поставками в Азию, Африку и Южную Америку. В американской номенклатуре её впоследствии заменила M15. Поэтому внешне похожие круглые корпуса могут относиться к разным поколениям изделий и иметь значительно различающуюся массу.',
    'Для M6A2 указаны диаметр 33 см, высота 8,3 см и полная масса 9,1 кг. Внутри семейства отдельно существует индекс M6A1. Он обозначает другую модификацию; приведённые здесь характеристики относятся именно к M6A2.',
    country='США')
add('eng-pma-1a',
    'PMA-1A — югославская противопехотная мина, относимая в историческом описании к 1960–1970-м годам. Её появление связано с развитием более ранней PMA-1. Главное наглядное изменение — материал: деревянный корпус предшественницы сменился чёрным бакелитовым.',
    'Бакелит — твёрдая пластмасса, поэтому тёмный корпус PMA-1A отличается от деревянного не только окраской, но и характером поверхности. Эта модель показывает, как внутри одной номенклатуры могли меняться наружные материалы при сохранении близкого названия.',
    'PMA-1A следует отличать и от PMA-1, и от круглых PMA-2 и PMA-3. Цифра в обозначении сама по себе не задаёт общую форму всех моделей линии. Указанные ниже 200 г относятся к основному заряду, а не к полной массе PMA-1A.')
add('eng-pma-2',
    'PMA-2 — югославская противопехотная мина с круглым пластиковым корпусом. За сходство с небольшой банкой она известна под прозвищем «Паштет». На верхней стороне особенно заметна деталь с шестилучевым контуром, которая выделяет модель среди простых круглых дисков.',
    'Корпус описан как полистирольный. На справочных изображениях встречается тёмно-зелёное исполнение, но известны и другие цвета. Прозвище связано с общими очертаниями предмета, а не с единым цветовым стандартом.',
    'Полная масса PMA-2 составляет 135 г, диаметр — 6,8 см, высота — 6,1 см. Несмотря на общие буквы в обозначении, она отличается от бакелитовой PMA-1A и от PMA-3 с её характерным наружным соединением двух половин. Каждая из этих моделей сохраняет собственные характеристики.')
add('eng-pma-3',
    'PMA-3 — югославская противопехотная мина, продолжающая линию PMA после PMA-1A и PMA-2. Её низкий круглый корпус образован двумя пластиковыми половинами. По окружности заметно чёрное резиновое соединение — одна из характерных деталей наружного облика.',
    'Внешне PMA-3 ближе к плоскому диску, чем PMA-2 с выраженной шестилучевой деталью сверху. Такое сравнение помогает увидеть изменение конструкции внутри линии: похожие названия объединяют происхождение, но не одинаковые корпуса.',
    'Для PMA-3 здесь подтверждена масса взрывчатого содержимого 35 г. Полная масса и точные наружные габариты в использованной записи не установлены. Значения соседней PMA-2 к ней не относятся; этот пробел оставлен открытым, чтобы не создавать вымышленный паспорт модели.')

add('eng-nr-413',
    'NR-413 — бельгийская противопехотная осколочная мина с вытянутым узким корпусом. На справочном изображении показан коричневый экземпляр на длинной стальной стойке. Соотношение узкого корпуса и длинной наружной опоры делает её силуэт особенно характерным.',
    'В исторических материалах по Ливии NR-413 встречается рядом с бельгийскими NR-109 и NR-442. Это самостоятельные модели: общие буквы NR не превращают их в варианты одного корпуса. Для NR-413 отдельно указаны диаметр 46 мм и длина корпуса без стойки 230 мм.',
    'Размер самой стойки не входит в приведённую длину корпуса. Также отдельно следует читать 95 г взрывчатого содержимого: это не полная масса изделия. Такая граница между корпусом, наружной опорой и содержимым позволяет правильно представить пропорции NR-413, не приписывая ей чужие размеры.')
add('eng-sb-33-family',
    'SB-33 — итальянская противопехотная мина компании BPD с низким круглым корпусом. На тёмно-зелёном образце заметны мелкая фактура наружной поверхности и тёмная центральная область сверху. По силуэту она входит в многочисленную группу компактных пластиковых мин, но имеет собственную производственную историю.',
    'С SB-33 связаны лицензионные обозначения EM-20 в Греции, M/412 в Португалии и P-5 в Испании. Поэтому одна исходная конструкция встречается в справочниках под разными национальными названиями. Страна изготовления конкретного экземпляра определяется его происхождением и маркировкой, а не только сходством формы.',
    'SB-33AR выделяется как отдельное исполнение. В размерной записи семейства приведены 8,5×3 см, а масса взрывчатого содержимого составляет 35 г. Эта величина описывает содержимое, не весь корпус; характеристики вариантов ниже сохраняют свои полные обозначения.')
add('eng-vs-50-family',
    'VS-50 — итальянская противопехотная мина компании Valsella с низким круглым корпусом. На описанном образце наружная часть светлая, верхняя центральная поверхность темнее, а по окружности проходят рёбра. Такое сочетание деталей придаёт простому дисковому силуэту узнаваемую фактуру.',
    'История VS-50 включает лицензионное сингапурское обозначение SPM-1. Отдельно встречается исполнение EO-3. Национальная копия и модификация относятся к линии VS-50, но дополнительные индексы сохраняют значение: они не являются случайными вариантами написания.',
    'Для VS-50 приводятся полная масса 185 г и габариты 9×4,5 см. Итальянская TS-50 внешне похожа, однако принадлежит другой линии изделий. Совпадение размеров и формы не делает названия VS-50 и TS-50 взаимозаменяемыми.')
add('eng-ts-50',
    'TS-50 — итальянская противопехотная мина с небольшим низким круглым корпусом. На описанном образце видны песочный оттенок, рёбра по наружной окружности и круглая центральная область сверху. Внешний рисунок корпуса близок к ряду других компактных итальянских мин.',
    'С этой конструкцией связано иранское обозначение YM-I. Производственная связь помогает понять, почему в справочниках встречаются близкие по виду изделия с разными названиями. При этом TS-50 и VS-50 относятся к разным линиям: сходство силуэта и близкие размеры не подтверждают тождество моделей.',
    'Размерная запись TS-50 составляет 9×4,5 см. Отдельно приводится 50 г взрывчатого содержимого; полная масса в этой записи не дана. Число в названии здесь не следует читать как полную массу предмета или как универсальный размер корпуса.')
add('eng-vs-jap',
    'VS-JAP — итальянская противопехотная осколочная мина компании Valsella Meccanotecnica. Она отличается от небольших дисков VS-50 высоким пластиковым корпусом с крупными гранями. На описанном изображении нижняя часть тёмная, верхняя многогранная часть светлее.',
    'Диаметр изделия составляет 130 мм, высота — 190 мм, полная масса — 2,8 кг. Эти пропорции объясняют массивный вертикальный силуэт: VS-JAP не выглядит как увеличенная копия низкой круглой VS-50. Над корпусом видны выступающие детали, которые также влияют на общий облик.',
    'Обозначение VS-JAP относится к самостоятельной модели. Начальные буквы VS связывают её с продукцией Valsella, но внутри этой номенклатуры существуют изделия разного класса, формы и массы. Для сравнения с VS-SAPF-M3 следует использовать отдельные характеристики обеих моделей.',
    country='Италия; Valsella Meccanotecnica')
add('eng-vs-mk2-family',
    'VS-Mk-2 — итальянская противопехотная мина Valsella Meccanotecnica с низким круглым пластиковым корпусом и каучуковой крышкой. По ободу проходят наружные рёбра, а в центре верхней поверхности заметна небольшая тёмная область. Общие пропорции близки к плоскому диску.',
    'Для базовой модели указаны диаметр 90 мм, высота 32 мм и полная масса 135 г. В другом размерном рисунке высота составляет 33 мм. Небольшое расхождение сохранено рядом с соответствующим обозначением, без выбора одного значения как единственно возможного.',
    'Название встречается в написаниях VS-Mk-2 и VS-Mk2. Вариант VS-Mk2-EL выделен отдельно: дополнительные буквы обозначают исполнение, а не просто другую расстановку дефисов. Числа базовой модели не заменяют отсутствующую самостоятельную спецификацию EL.',
    country='Италия; Valsella Meccanotecnica')
add('eng-vs-sapf-m3',
    'VS-SAPF-M3 — итальянская противопехотная осколочная мина компании Valsella Meccanotecnica. Её пластиковый корпус имеет форму сравнительно широкого цилиндра. На изображении он тёмный, с круглой верхней поверхностью и наружными упругими деталями по сторонам.',
    'Диаметр 128 мм при высоте 105 мм придаёт корпусу более приземистые пропорции, чем у высокой гранёной VS-JAP. При этом VS-SAPF-M3 — значительно более массивное изделие, чем небольшие дисковые VS-Mk-2: полная масса составляет 2,5 кг.',
    'Такие различия показывают разнообразие противопехотных моделей Valsella. Общее начало VS в названии обозначает принадлежность к производственной номенклатуре, а не одинаковую геометрию. Для VS-SAPF-M3 ниже приведены её собственные параметры, отдельно от других изделий этой компании.',
    country='Италия; Valsella Meccanotecnica')
add('eng-vs-1-6-family',
    'VS-1.6 — итальянская противотанковая мина Valsella с пластиковым корпусом, усиленным наружными рёбрами. Низкая дискообразная форма сочетается с широкой окружной частью и выступающей круглой поверхностью сверху. Она заметно крупнее компактных противопехотных моделей VS-50 и VS-Mk-2.',
    'Внутри линии встречаются обозначения VS-1.6, VS-1.6 MOD 1 и VS-1.6-AR/AN. Разные исполнения имеют собственные размерные записи: для MOD 1 приведены диаметр 222 мм и высота 92 мм, а для другого рисунка VS-1.6 — 233 мм и 90 мм.',
    'Масса 3,0 кг указана без взрывателя. Это характеристика определённой комплектации, а не универсальная полная масса любого варианта VS-1.6. Отличающиеся значения диаметра и высоты ниже оставлены с индексами соответствующих исполнений.')
add('eng-vs-av-family',
    'VS-2.2, VS-3.6, VS-6.0 и VS-9.0 — обозначения итальянской противотанковой линии VS. Подробно здесь представлены VS-2.2 и VS-3.6 компании Valsella. У них округлые пластиковые корпуса, выступающая центральная часть сверху и выраженные наружные рёбра по окружности.',
    'Для двух описанных моделей высота составляет 115 мм, но диаметр и масса различаются. VS-2.2 имеет диаметр 230 мм и массу без взрывателя 3,5 кг; VS-3.6 — 248 мм и 5,0 кг. Сходный профиль таким образом объединяет изделия заметно разного размера.',
    'У VS-2.2 также различаются исполнения TYPE 1 и TYPE 2, для которых приведены самостоятельные габариты. Подробные параметры VS-6.0 и VS-9.0 в этой записи не установлены. Цифры из их названий не подставлены вместо отсутствующих паспортных характеристик.')
add('eng-tmrp-6',
    'TMRP-6 — югославская противотанковая мина с низким круглым пластиковым корпусом. На оливковом образце заметны радиальные рёбра, наклонная верхняя поверхность и приподнятая центральная область. Этот рельеф отличает её от более простых гладких дисковых корпусов.',
    'Диаметр корпуса составляет 290 мм, а его высота в одной записи — 132 мм. Общая высота с наружными деталями в другом описании приведена как 140 мм без дополнительного стержня. Фотографии разной комплектации поэтому могут показывать несколько отличающиеся пропорции.',
    'Полная масса указана двумя значениями — 7,2 кг и 7,8 кг. Объяснение этого расхождения не установлено, поэтому меньшая величина не переименована в массу пустого корпуса. TMRP-6 остаётся отдельной моделью относительно семейства TMA, несмотря на общую югославскую номенклатуру.')
add('eng-type-72-ap-family',
    'Китайская противопехотная Type 72 — семейство компактных мин с низким круглым корпусом. Оно включает обозначения A, B и C. На описанном образце Type 72A виден зелёный корпус с плоской верхней поверхностью; этот внешний вид относится именно к показанному варианту A.',
    'Для Type 72A приводятся полная масса 140 г, ширина 78 мм и высота 38 мм. В другой записи Type 72 AP размеры немного отличаются. Такой небольшой предмет по масштабу и пропорциям резко отличается от крупной противотанковой Type 72, хотя основная часть названия совпадает.',
    'Type 72 выпускавшегося в ЮАР происхождения имеет отдельную карточку. Общее название объясняет родство конструкций, но не устанавливает страну изготовления конкретного экземпляра. Дополнительные буквы вариантов и уточнение AP следует сохранять при сравнении моделей.')
add('eng-type-72p-av',
    'Противотанковая Type 72 — китайская мина с широким невысоким пластиковым корпусом. На изображении видны радиальные рёбра вокруг центральной верхней области и боковая ручка. Это крупное круглое изделие, существенно отличающееся от небольшой противопехотной Type 72.',
    'Производственная история связана также с ЮАР и Ираном. Для родственного иранского исполнения известно обозначение YM-III. Такая география объясняет несколько национальных названий близкой конструкции, но не позволяет определить изготовителя только по общей форме корпуса.',
    'В каталоге название дополнено «(P)» и указанием противотранспортного класса. Для китайской Type 72 AT приведены диаметр корпуса 270 мм и высота 100 мм. Записи полной массы и взрывчатого содержимого расходятся между собой; ниже они оставлены с исходными определениями, без попытки сложить их в характеристику одного экземпляра.',
    country='Китай; родственные изделия производились также в ЮАР и Иране')
add('mine-audit-v25-su-tm-44',
    'ТМ-44 — советская противотанковая мина периода Второй мировой войны. Она относится к военной номенклатуре, предшествовавшей широко известным послевоенным ТМ-57 и семейству ТМ-62. Исторический индекс важно сохранять целиком: сходные обозначения разных лет не означают одинаковые изделия.',
    'В послевоенном американском справочнике для ТМ-44 приведены приблизительная полная масса 16 фунтов и масса основного заряда 12 фунтов. Округлённые значения отражают характер той исторической записи, поэтому переводы в килограммы ниже также имеют знак приблизительности.',
    'Подтверждённые наружные габариты здесь отсутствуют. Размеры других советских мин военного времени, в частности ТМ-41, к ТМ-44 не перенесены. Карточка описывает конкретное историческое название и имеющиеся данные, сохраняя открытым вопрос о полном размерном паспорте.')
add('mine-audit-v25-su-tmd-40',
    'ТМД-40 — советская деревянная противотанковая мина периода Второй мировой войны. Её наружная форма напоминает длинный прямоугольный ящик. Это заметное отличие от круглых металлических корпусов: вытянутость и прямые грани определяют общий облик модели.',
    'В исторической размерной записи длина составляет приблизительно 23,5 дюйма, ширина — 5,5 дюйма, высота — 4 дюйма. Таким образом, длина корпуса более чем вчетверо превосходит ширину. Пропорции позволяют представить изделие даже без изображения: это узкий продолговатый предмет, а не квадратная коробка.',
    'Полная масса приведена диапазоном 11–12 фунтов. Деревянная ТМД-40 имеет собственные размеры и не совпадает с более поздней ТМД-44, корпус которой заметно ближе к широкому прямоугольному ящику. Общие буквы ТМД объединяют номенклатуру, а не одну неизменную конструкцию.')
add('mine-audit-v25-su-tmd-44',
    'ТМД-44 — советская деревянная противотанковая мина, связанная с периодом Второй мировой войны и ранними послевоенными годами. Корпус имеет форму сравнительно широкого прямоугольного ящика. Этим она отличается от длинной узкой ТМД-40, несмотря на близкие названия.',
    'Для одного описанного исполнения приведены габариты 315×280×158 мм и полная масса 10 кг. Длина и ширина здесь сравнительно близки, поэтому корпус выглядит массивной коробкой. Дерево определяет не только материал стенок, но и характер видимых граней и соединений.',
    'У деревянных изделий встречаются различия исполнения; историческое описание отдельно предупреждает о возможном изменении размеров и массы. Значения ниже относятся к приведённой записи ТМД-44. Их не следует превращать в точный паспорт любого старого деревянного корпуса с похожими пропорциями.')
add('ref-v9-su-tmdb',
    'ТМД-Б — советская деревянная противотанковая мина с широким коробчатым корпусом. На описанных образцах встречаются тёмно-зелёная окраска и неокрашенное дерево, а сбоку видна тканевая ручка. Прямые грани и древесная поверхность придают ей облик небольшого ящика.',
    'Размерная запись составляет 32×29×16 см. Длина и ширина близки, поэтому ТМД-Б по пропорциям отличается от длинной узкой ТМД-40. Общий деревянный материал связывает их внешне, но не означает совпадения размеров и внутреннего исполнения.',
    'Для взрывчатого содержимого приводится диапазон 5–7 кг. Он не является полной массой мины: деревянный корпус и другие части относятся к отдельной величине. Исторические описания деревянных мин сохраняют различия комплектации, поэтому здесь не задано одно точное значение для всех ТМД-Б.')
add('eng-tma-family',
    'TMA — югославское семейство противотанковых мин, в котором встречаются разные формы и материалы наружной конструкции. Среди описанных моделей есть округлые пластиковые корпуса, призматические и прямоугольные изделия, а также бескорпусная TMA-3. Общее название не обозначает один корпус с последовательно меняющимися цифрами.',
    'Основная размерная запись этой карточки относится к TMA-4 югославского и сербского происхождения. Её текстолитовый корпус круглый и низкий: диаметр составляет 285 мм, высота — 110 мм, полная масса — 6 кг. На изображении найденного образца видны плоская верхняя поверхность и три круглых отверстия.',
    'Другие модели ниже описаны отдельно. Одинаковая масса TMA-1A и TMA-4 не делает их одним изделием, а прямоугольная TMA-5 заметно отличается по геометрии от округлых представителей линии. Эта разница форм — одна из наиболее интересных особенностей семейства.',
    country='Югославия; для TMA-4 также указана Сербия',
    sections={
        'Описание TMA-1A':'TMA-1A имеет округлый пластиковый корпус из материала, обозначенного как «ювидур». Полная масса составляет 6 кг. Это самостоятельная модель: совпадение массы с TMA-4 не означает одинакового материала и корпуса.',
        'Описание TMA-2A':'TMA-2A отличается призматической формой пластикового корпуса. Материал также назван «ювидур», а полная масса составляет 7 кг. Внутри семейства это пример другой геометрии по сравнению с округлыми TMA-1A и TMA-4.',
        'Описание TMA-5 / TMA-5A':'TMA-5 и TMA-5A имеют отдельные обозначения; для каждой приведена полная масса 5,6 кг. На изображении TMA-5 виден зеленоватый прямоугольный корпус. Фотография относится к TMA-5 и не подтверждает отдельно внешний вид TMA-5A.',
        'Описание TMA-3':'TMA-3 описывается как бескорпусная мина с защитой стекловолокном и боковой тканевой ручкой. Округлый зеленоватый контур на фотографии относится к конкретному образцу. Приблизительная полная масса составляет 7,5 кг; данные текстолитовой TMA-4 сюда не относятся.'})
add('ordnance-v27-km14-respublika-koreya',
    'KM14 — южнокорейское обозначение модели, связанной с американской противопехотной M14. Здесь показано учебное изделие Koryo Pyrotechnics: небольшой круглый пластиковый корпус воспроизводит внешнюю форму боевой мины, но имеет собственные учебные компоненты.',
    'Для учебного корпуса указаны диаметр 55,6 мм, высота 42 мм и масса 51 г. Отдельный дымовой элемент имеет размеры 44,5×13 мм и массу 18 г. Это характеристики разных частей учебного изделия; их не следует выдавать за полную массу боевой KM14.',
    'Для исходной американской M14 в другой записи приведены 56×40 мм и полная масса 99,4 г. Сопоставление показывает близость наружного масштаба, но не одинаковую комплектацию. Учебное назначение относится к опубликованному образцу Koryo, а не автоматически к любому похожему предмету.')
add('ordnance-v27-km16-respublika-koreya',
    'KM16 — южнокорейская модель семейства мин с высоким цилиндрическим металлическим корпусом. В этой карточке представлен учебный образец Koryo Pyrotechnics, связанный изготовителем с боевыми KM16A1 и KM16A2. Выступающие верхние детали заметно меняют общую высоту изделия.',
    'Учебный корпус имеет диаметр 101,5 мм, высоту 135 мм и массу 2,8 кг. Отдельный учебный взрыватель имеет габариты 19,6×114 мм и массу 106 г, а дымовой элемент — 12,8×72,4 мм и 16 г. Эти части не входят в определение массы только корпуса. Данные учебной комплектации не заменяют паспорт боевых A1 и A2.',
    'История названия имеет и документированную современную страницу: в августе 2024 года учебная KM16 использовалась морскими пехотинцами Республики Корея на двустороннем обмене KMEP 24.2. Фотография относится именно к учебному изделию, поэтому её подпись сохраняет эту важную особенность.')
add('ordnance-v27-km18a1-respublika-koreya',
    'KM18A1 — южнокорейская направленная мина с характерным изогнутым прямоугольным корпусом. Общий силуэт родственен американской M18A1 Claymore. Здесь изображена учебная версия Koryo Pyrotechnics на складных опорах, а не подтверждённый боевой экземпляр.',
    'Историческая запись сообщает о выпуске компанией Korea Explosives около 7000 боевых KM18A1 в 2000 году. Эта цифра относится к конкретному году и производству боевой модели; она не описывает объём современного выпуска учебного изделия Koryo.',
    'Две заводские страницы учебной версии расходятся в размерах и массе: корейская приводит 216×102 мм и 0,85 кг, английская — 215×130 мм и 1,2 кг. Причина различий не объяснена. Обе записи ниже сохранены отдельно и не перенесены на боевую KM18A1.')

add('grenade-m67',
    'M67 — американская ручная осколочная граната с шарообразным стальным корпусом. Основная поверхность гладкая, без глубокого наружного рельефа старой Mk 2. Компактная округлая форма — наиболее заметная особенность её внешнего облика; детали запала выступают над основным корпусом.',
    'Диаметр корпуса составляет 63,5 мм, максимальная высота со взрывателем — 89,6 мм. Полная масса 14 унций, примерно 397 г, включает изделие со взрывателем. Разница между диаметром шара и общей высотой объясняется выступающей верхней частью, а не вытянутой формой самого корпуса.',
    'Учебная M69 повторяет общий силуэт M67, однако имеет собственное обозначение и другую комплектацию. M67 представлена также в продукции Nammo: американское происхождение модели и название современного изготовителя описывают разные стороны её истории.',
    country='США — происхождение модели; M67 представлена также в продукции Nammo',
    evidence=[{'url':'https://www.nammo.com/products/grenades-warheads-energetics/m67-grenade/','claims':'Стальной шарообразный корпус, диаметр, высота и масса изделия со взрывателем. Дистанции и задержки не переносились.'}])
add('grenade-dm51',
    'DM51 — немецкая ручная граната с характерной бочкообразной наружной частью. Её конструкция объединяет внутренний фугасный корпус и отдельную осколочную оболочку. Такое разделение объясняет, почему внешний объём DM51 заметно больше её внутренней центральной части.',
    'Наружная оболочка выполнена из литой пластмассы со встроенными стальными шариками. Пластик здесь не означает отсутствие металлических осколочных элементов: он составляет внешнюю основу составной оболочки. Это важное отличие от гранат, у которых наружная оболочка сама изготовлена из массивного металла.',
    'В основной описанной конфигурации полная масса составляет около 450 г. Известны внешние исполнения и учебные изделия; конкретные цвета и маркировка относятся к соответствующему образцу. Общее название DM51 объединяет немецкую номенклатуру, но не подтверждает одинаковую комплектацию всех похожих корпусов.',
    country='Германия; граната номенклатуры Бундесвера',
    evidence=[{'url':'https://www.bundeswehr.de/de/ausruestung-technik-bundeswehr/ausruestung-bewaffnung/handgranate-dm51','claims':'Бочкообразная наружная часть, внутренний фугасный корпус, литая пластиковая осколочная оболочка со стальными шариками, полная масса около 450 г. Способы изменения конфигурации исключены.'}])
add('ordnance-v27-rkg-3-rkg-3',
    'РКГ-3 — ручная кумулятивная противотанковая граната. Её внешний облик совсем не похож на небольшой округлый корпус Ф-1 или РГД-5: здесь заметны цилиндрическая основная часть и длинная рукоятка. Такое сочетание деталей образует вытянутый силуэт.',
    'Полная масса составляет 1070 г, то есть более килограмма, а габаритная запись — 362×72 мм. Внешняя комплектация включает также небольшой белый парашют, показанный на отдельных изображениях. Он относится к конструкции этой группы, но его видимость на фотографии зависит от состояния показанного образца.',
    'РКГ-3М и РКГ-3ЕМ — самостоятельные модификации. Они связаны с базовой РКГ-3, однако дополнительные буквы обозначают конкретное исполнение. Описание одной модификации нельзя превращать в общую характеристику всех гранат с начальным индексом РКГ-3.')
add('ordnance-v27-vog-17-vog-17m',
    'ВОГ-17 и ВОГ-17М — близкие варианты 30-мм осколочных гранатомётных боеприпасов. Это компактные вытянутые изделия, существенно отличающиеся от ручных гранат. Обозначение ВОГ относится к гранатомётному выстрелу, поэтому внешний масштаб и форма здесь определяются другой группой боеприпасов.',
    'На справочных изображениях виден небольшой тёмный корпус. ВОГ-17 и ВОГ-17М выглядят почти одинаково; одинаковый силуэт не делает их одним индексом. Название варианта и заводские обозначения сохраняют значение даже при близком наружном исполнении.',
    'В приведённой записи масса составляет 350 г, а габариты — 132×30 мм. ВОГ-25 относится уже к другой, 40-мм группе и имеет иной размерный паспорт. Общие буквы ВОГ объединяют номенклатуру гранатомётных изделий, а не одну универсальную конструкцию.')
add('ordnance-v27-vog-25',
    'ВОГ-25 — 40-мм осколочный гранатомётный боеприпас с коротким цилиндрическим корпусом. Он заметно толще относительно длины, чем изделия 30-мм линии ВОГ-17. На передней части отдельных экземпляров видны заводские обозначения.',
    'Для ВОГ-25 указаны масса 250 г и габариты 102×40 мм. Это параметры самого боеприпаса, а не ручной гранаты с отдельным выступающим запалом. Различие классов помогает понять, почему внешне похожие небольшие металлические предметы могут иметь совершенно разные названия.',
    'ВОГ-25М — другая модель с собственными характеристиками. Отдельно описываются и полевые переделки на основе ВОГ-25: их наружный облик не является стандартным заводским исполнением исходного изделия. Данные таких переделок не включены в общий паспорт ВОГ-25.')
add('ordnance-v27-vog-25m',
    'ВОГ-25М — 40-мм осколочный гранатомётный боеприпас, выделенный отдельно от ВОГ-25. Общий силуэт остаётся коротким и цилиндрическим, однако близость формы не означает полного совпадения конструкции и характеристик.',
    'Масса ВОГ-25М составляет 278 г, а габариты — 107×40 мм. При том же калибре он несколько длиннее и тяжелее ВОГ-25, для которого приведены 102×40 мм и 250 г. Сравнение показывает, что дополнительная буква в индексе соответствует самостоятельному исполнению.',
    'В той же группе встречается внешне сходный ВОГ-25ПМ; отдельно известно болгарское обозначение ARFG-25B. Эти названия необходимо сохранять целиком. Подтверждённое родство номенклатуры не превращает все похожие 40-мм изделия в один ВОГ-25М.')
add('ordnance-v27-m430a1-hedp',
    'M430A1 HEDP — американская 40-мм граната двойного назначения. Сокращение HEDP указывает на сочетание кумулятивного и осколочного действия. Это гранатомётное изделие с компактным цилиндрическим корпусом, а не ручная граната сферической формы.',
    'Габариты данной записи составляют 112×40 мм, масса — 340 г. Диаметр описывает калибр гранаты, тогда как полная длина показывает её вытянутые пропорции. Сходный калибр ВОГ-25 сам по себе не означает одинаковой модели или конструкции.',
    'Индекс A1 обозначает конкретный вариант линии M430. В материалах о полевых переделках встречаются изделия на основе M430A1, однако их точное наружное исполнение не установлено. Поэтому изображения переделок не использованы как единый шаблон внешнего вида заводской гранаты.')
add('ordnance-v29-ga-0106',
    'SOHG — семейство модульных фугасных ручных гранат Nammo. Его главное отличие от гранат с фиксированным корпусом заключается в существовании нескольких конфигураций. Поэтому название семейства описывает конструктивную линию, а не одно изделие неизменной высоты и массы.',
    'Размеры, приведённые здесь, относятся к одному модулю: диаметр корпуса 53 мм, высота со взрывателем 85 мм. Масса того же модуля составляет 230 г со взрывателем и 190 г без него. Различие двух значений объясняется комплектацией, а не разными определениями массы корпуса.',
    'Также существуют разные варианты основного вещества. Они приведены отдельно с собственными значениями массы. Характеристики одного модуля не описывают многомодульное изделие; внешний вид одной конфигурации также не представляет всю линию SOHG.')
add('ordnance-v29-ga-0107',
    'TTC Smoke — дымовая ручная граната Nammo, выделенная в самостоятельную линию изделий. Её назначение связано с образованием дыма, поэтому она относится к другой группе, чем осколочные M67 или фугасные HGO. Общая принадлежность к ручным гранатам не означает одинакового внутреннего содержимого.',
    'Изделие имеет диаметр 66 мм и длину 155 мм при полной массе 600 г. Эти размеры характеризуют заметно вытянутый предмет. Сочетание длины и диаметра полезнее для представления его масштаба, чем сравнение только по массе с округлой осколочной гранатой.',
    'Полное обозначение TTC Smoke отделяет эту модель от других дымовых изделий Nammo. Точная марка дымового состава в имеющейся записи не раскрыта. Характеристики соседних дымовых гранат с похожими названиями сюда не перенесены.')
add('ordnance-v29-ga-0105',
    'Training Hand Grenade — учебная ручная граната Nammo, создаваемая с использованием деталей серийных моделей. Инертное заполнение корпуса воспроизводит массу и баланс боевого образца. Поэтому сходство внешней формы здесь является особенностью учебного изделия, а не случайным совпадением.',
    'В описанной комплектации отдельно упомянут пиротехнический сигнальный компонент. Слова «инертное заполнение» относятся к основному содержимому корпуса и не означают, что все части комплектного изделия являются простым неподвижным макетом.',
    'Название Training Hand Grenade объединяет учебное предложение изготовителя; оно не заменяет точный индекс исходной боевой модели. Масса и размеры зависят от конкретного исполнения. Поэтому параметры M67 или других серийных гранат здесь не приведены как универсальный паспорт учебной линии.')
add('ordnance-v29-ga-0155',
    'AN-M14 — американская зажигательная ручная граната. Её цилиндрический корпус изготовлен из тонкого листового металла, а основное содержимое относится к термитному типу и обозначается TH3. По классу она отличается и от осколочных, и от дымовых гранат.',
    'В описанном исполнении корпус светло-красный, с чёрной маркировкой. Длина составляет около 145 мм, диаметр — около 64 мм. При близких размерах AN-M8 и M18 эта модель имеет другое назначение: общая форма металлического цилиндра не означает одинаковый боеприпас.',
    'Полная масса AN-M14 составляет 32 унции, примерно 907 г. Она относится ко всему изделию, тогда как масса основного вещества приведена отдельно. Красная окраска описывает конкретное исполнение; исторические и учебные образцы требуют собственной подписи.')
add('ordnance-v29-ga-0156',
    'AN-M8 — американская ручная дымовая граната с белым дымом. Основное дымовое содержимое обозначается HC. Это отличает её от M18, у которой предусмотрены цветные дымовые варианты, хотя внешние размеры двух моделей близки.',
    'Корпус AN-M8 цилиндрический, из тонкого листового металла. В описанном исполнении он светло-зелёный, с чёрными обозначениями. При длине около 145 мм и диаметре около 64 мм предмет имеет вытянутые пропорции небольшой металлической банки.',
    'Полная масса составляет 24 унции, приблизительно 680 г. Эта величина заметно больше массы описанной M18, но не является массой только дымового содержимого. Сопоставление двух моделей показывает, почему форму, массу и полное обозначение необходимо рассматривать вместе.')
add('ordnance-v29-ga-0158',
    'M18 — американская ручная граната для цветного дымового сигнала. Известны исполнения с красным, зелёным, жёлтым и фиолетовым дымом. Все эти варианты сохраняют основное обозначение M18: цвет дыма относится к исполнению одной линии.',
    'Наружный корпус цилиндрический, тонкостенный металлический. В описанном варианте он светло-зелёный с чёрной маркировкой. Цвет наружной поверхности и цвет образуемого дыма — разные характеристики, поэтому зелёный корпус сам по себе не обозначает зелёный дым.',
    'Диаметр составляет около 64 мм, длина — около 146 мм, полная масса — примерно 539 г. От дымовой AN-M8 модель отличается не только цветными вариантами, но и отдельной массовой записью. Размеры и масса ниже относятся к комплектной M18, а не к транспортной упаковке.')
add('ordnance-v29-ga-0169',
    'M84 — американская светозвуковая ручная граната. Её основное содержимое относится к пиротехническому светозвуковому составу, а не к основному заряду обычной осколочной модели. Поэтому небольшой размер гранаты не объясняет сам по себе её класс.',
    'Стальной корпус имеет шестигранное сечение. В описанном наружном исполнении упомянута светло-зелёная круговая полоса. Гранёная форма заметно отличает M84 от шарообразной M67 и от гладких цилиндрических дымовых гранат.',
    'Максимальная длина составляет около 133 мм, приблизительная масса со взрывателем — 425 г. Величина 3,5 г описывает отдельное основное содержимое, а не весь предмет. Классификационный термин «несмертельная» не является обещанием отсутствия опасности или травм.')
add('ordnance-v29-ga-0182',
    'Mk 2 — американская ручная осколочная граната с литым чугунным корпусом и глубоким наружным рельефом. Выраженные сегменты образуют характерную фактуру, заметно отличающую её от гладкой M26 и шарообразной M67.',
    'В описанных вариантах корпус обычно оливковый. Длина комплектного изделия не превышает примерно 114 мм, диаметр составляет около 57 мм. Чугунная оболочка придаёт Mk 2 сравнительно массивный внешний облик, хотя сами габариты остаются небольшими.',
    'Полная масса указанного исполнения — 21 унция, приблизительно 595 г. Это самостоятельная модель со своим материалом корпуса и характеристиками. Учебные и музейные предметы похожей формы следует подписывать отдельно: характерный рельеф рассказывает о конструкции, но не о состоянии конкретного предмета.')
add('ordnance-v29-ga-0172',
    'M26 — американская ручная осколочная граната с гладкой тонкостенной стальной оболочкой. Элемент для образования осколков находится внутри корпуса, поэтому глубокий наружный клетчатый рисунок Mk 2 здесь отсутствует. Это заметное различие двух конструктивных подходов.',
    'В описанном исполнении корпус оливковый. Диаметр составляет около 57 мм, длина комплектной гранаты — не более примерно 99 мм. Полная масса 16 унций, приблизительно 454 г, относится к изделию в указанной комплектации.',
    'M26A1 имеет очень близкий наружный корпус, но отличается внутренним исполнением. M26 и M26A1 потому нельзя разделить только по общему силуэту. Основные численные значения ниже подписаны именно M26; сходство оболочек не делает два индекса равнозначными.')
add('ordnance-v29-ga-0173',
    'M26A1 — модификация американской ручной осколочной гранаты M26. Её гладкая стальная оболочка внешне близка к базовой модели, а основные различия относятся к внутреннему исполнению. Внутри корпуса расположен отдельный осколочный элемент.',
    'Для описанного изделия приведены диаметр около 57 мм, длина не более примерно 99 мм и полная масса около 454 г. Наружная окраска оливковая. Близость этих параметров к M26 соответствует общему корпусу, но не отменяет самостоятельного обозначения A1.',
    'Основной заряд и дополнительные внутренние элементы в таблице перечислены раздельно. Их отдельные массы не являются массой комплектной гранаты. При сравнении M26A1, M26 и M61 следует сохранять полные индексы, поскольку похожая оболочка объединяет несколько разных исполнений.')
add('ordnance-v29-ga-0179',
    'M61 — американская ручная осколочная граната с гладкой тонкостенной стальной оболочкой и внутренним осколочным элементом. По общему корпусу она близка к M26 и M26A1. Одно из описанных наружных отличий — дополнительный предохранительный элемент.',
    'Оливковый корпус имеет диаметр около 57 мм; длина комплектного изделия не превышает примерно 99 мм. Полная масса составляет около 454 г. Совпадение основных габаритов с близкими моделями объясняет, почему один силуэт не устанавливает полный индекс.',
    'Название M61 выделяет самостоятельное исполнение внутри этой группы. Отдельные внутренние компоненты и основной заряд перечислены ниже со своими характеристиками. Эти сведения описывают комплектную модель и её части раздельно, не превращая M61 в другое название M26A1.')
add('ordnance-v29-ga-0191',
    'M69 Practice — американская учебная ручная граната, повторяющая шарообразную форму M67. Стальной корпус и близкая масса сохраняют внешний масштаб боевой модели. В описанном исполнении корпус синий, с коричневой полосой и белыми обозначениями.',
    'Основное боевое заполнение корпуса отсутствует, но штатная учебная комплектация включает пиротехнический запал. Это отличает M69 от простого цельного макета. Учебное назначение описывает конкретное исполнение и не является выводом о безопасности любого похожего шара.',
    'Полная масса составляет 14 унций, примерно 397 г; диаметр — около 64 мм, длина — не более примерно 90 мм. Близость к M67 относится к форме и масштабу, тогда как название M69 и учебная комплектация сохраняют самостоятельное значение.')
add('ordnance-v29-ga-0097',
    'GH S&F-CS — болгарская светозвуковая ручная граната с раздражающим действием. В этой линии светозвуковая классификация сочетается с обозначением CS. Это самостоятельная модель относительно обычных светозвуковых GH S&F и варианта GH S&F-CS-7.',
    'Наружные размеры составляют 51 мм по диаметру и 118 мм по высоте. Масса изделия в комплектации с AF14 не превышает 0,20 кг. Эти значения описывают сравнительно узкий вытянутый предмет, а не транспортную упаковку.',
    'Полный индекс особенно важен для этой группы: добавление «-7» обозначает другую модель, а не сокращённую подпись того же изделия. Масса основного содержимого отдельно не раскрыта. Поэтому параметры соседних вариантов не приведены как общие характеристики GH S&F-CS.')

add('artillery-krasnopol-family',
    '«Краснополь» — семейство управляемых артиллерийских снарядов советского происхождения. Исходный 152-мм ОФ-39 входит в комплекс 2К25. Длинный цилиндрический корпус, сужающаяся головная часть и аэродинамические поверхности придают ему характерный вытянутый силуэт.',
    'Историческая размерная запись исходного ОФ-39 даёт длину 1300 мм и полную массу 50 кг. Для развития «Краснополь-М» в том же сравнении указаны исполнения 152/155 мм, длина 955 мм и масса 43 кг. Сравнение показывает заметное изменение пропорций внутри семейства.',
    'Название «Краснополь-М2» относится к дальнейшей российской линии, связанной с холдингом «Высокоточные комплексы». Размеры раннего ОФ-39 не описывают автоматически М2. Также следует различать снаряд и комплекс: индекс 2К25 объединяет несколько изделий, тогда как ОФ-39 обозначает сам боеприпас.')
add('artillery-of-462',
    'ОФ-462 — советское обозначение 122-мм осколочно-фугасного артиллерийского снаряда. Буквы ОФ называют его основной класс. История семейства продолжилась и в зарубежном производстве: чешская STV GROUP предлагает HE-462 как эквивалент ОФ-462.',
    'Для изделия HE-462 приведены масса снаряда 21,76 кг и длина 552–564 мм. Эти пропорции относятся к вытянутому артиллерийскому корпусу. Диапазон длины сохранён: различия указанной комплектации изготовителем отдельно не объяснены.',
    'Снаряд, полный выстрел и транспортная упаковка — разные предметы учёта. В характеристиках ниже масса подписана именно для снаряда STV. Так советское название и современное зарубежное предложение представлены вместе, но параметры одного выпуска не объявлены универсальными для всей истории ОФ-462.')
add('artillery-of-25',
    'ОФ-25, также обозначаемый 3ОФ25, — советский 152-мм осколочно-фугасный артиллерийский снаряд. Стальной корпус вытянут, а головная часть сужается к носу. Это традиционный снаряд с единым основным корпусом, отличающийся по классу от кассетных носителей с отдельными внутренними боеприпасами.',
    'Для 3ОФ25 приведена полная масса снаряда 43,56 кг и габаритная запись 152×646 мм. Индекс относится к самому снаряду. Полный артиллерийский выстрел имеет другую комплектацию, поэтому его масса не совпадает с массой одного ОФ-25.',
    'Модель использовалась как сравнительный образец в российском патентном описании более поздней разработки. Это связывает советское изделие с последующей историей исследований, но характеристики новой конструкции остаются отдельными. Зарубежные 152-мм снаряды с общей подписью HE также не становятся ОФ-25 только из-за совпадения калибра.')
add('artillery-m795',
    'M795 — американский 155-мм осколочно-фугасный артиллерийский снаряд. Его стальной корпус вытянут, с заметным наружным металлическим ведущим пояском. Калибр характеризует размер корпуса, тогда как индекс M795 выделяет конкретную модель внутри многочисленной 155-мм номенклатуры.',
    'General Dynamics Ordnance and Tactical Systems связывает выпуск M795 с армией и морской пехотой США. Для описанного изделия приведены масса около 46,72 кг и длина со взрывателем около 843 мм. Высота отдельной головной детали потому уже входит в указанную полную длину.',
    'Внутри линии существуют исполнения с TNT и IMX-101. Они сохраняют основное название M795, но имеют разные обозначения основного вещества. В отличие от кассетных M864 и M483A1, описание M795 относится к осколочно-фугасному снаряду с единым основным корпусом.')
add('artillery-m982-excalibur',
    'M982 Excalibur — 155-мм управляемый артиллерийский снаряд, совместно разработанный Raytheon и BAE Systems Bofors. Его история объединяет американскую и шведскую промышленность. Основное отличие по классу — управляемое исполнение, выделенное в самостоятельное семейство артиллерийских боеприпасов.',
    'Внутри 155-мм линии существуют разные варианты и этапы развития. Для M982A1 Increment Ib EST приведена масса около 46,27 кг, а для других перечисленных исполнений — около 48,08 кг. Поэтому слово Excalibur не обозначает одно неизменное значение массы для всей линейки.',
    'Название используется также для морского направления N5 другого калибра. Эта ветвь не является вторым названием сухопутного M982. При сравнении моделей важно сохранять индекс и калибр: международное имя семейства объединяет историю разработки, но не одинаковые корпуса.')
add('artillery-bonus-155',
    'BONUS — 155-мм артиллерийский снаряд-носитель совместной шведско-французской разработки BAE Systems Bofors и Nexter. Внутри него находятся два самостоятельных сенсорных боевых элемента. Это определяет основной класс изделия: большой наружный снаряд и его внутренние элементы — разные части боеприпаса.',
    'Для BONUS MkII отдельно приведены масса носителя без взрывателя 44,6 кг и длина со взрывателем 898 мм. Каждый боевой элемент имеет собственную массу 6,5 кг. Размеры полного снаряда поэтому не характеризуют каждый небольшой внутренний элемент.',
    'В другой поставочной записи указаны масса 45 кг и длина без взрывателя 803 мм. Разница определения длины объясняет, почему два числа нельзя просто считать противоречащими габаритами одного корпуса. BONUS относится к тому же широкому классу сенсорных носителей, что и SMArt 155, но сохраняет самостоятельное происхождение и характеристики.')
add('ref-v10-artillery-m864',
    'M864 — американский 155-мм кассетный артиллерийский снаряд линии DPICM. Основной наружный корпус служит носителем отдельных внутренних боеприпасов. Такая конструкция отличает его от осколочно-фугасной M795 с единым основным корпусом.',
    'Модель относится к истории американских кассетных изделий второй половины XX века. В сводке армии США за 1988 финансовый год M864 уже назван находящимся в производстве. Эта дата подтверждает выпуск к тому времени, хотя точный год его начала здесь не установлен.',
    'Полная масса снаряда составляет примерно 46,27 кг, длина со взрывателем — около 920 мм. Масса всего M864 и масса одного внутреннего изделия существенно различаются. Ниже они подписаны отдельно, поскольку изображение внешнего носителя и фотография его содержимого показывают предметы разного масштаба.')
add('ref-v10-artillery-m483a1',
    'M483A1 — американский 155-мм кассетный артиллерийский снаряд. Его наружный корпус является носителем отдельных внутренних боеприпасов. Поэтому описание полного снаряда и описание небольшого отделившегося элемента относятся к разным предметам.',
    'Изделия с обозначением M483A1 документированы в полевом исследовании по Ливану 2006 года. Эта историческая запись связывает модель с конкретным конфликтом, но не устанавливает время изготовления каждого найденного экземпляра.',
    'Для полного снаряда приведены масса около 46,54 кг и длина со взрывателем около 899 мм. По габаритам он близок к кассетной M864, однако это самостоятельная модель. Совпадение калибра и близкий размер наружного корпуса не означает одинакового внутреннего исполнения.')
add('ref-v10-artillery-smart-155',
    'SMArt 155 — немецкий 155-мм артиллерийский снаряд-носитель с двумя сенсорными боевыми элементами. Сокращение SFM в его классификации означает Sensor Fuzed Munition. В отличие от обычного осколочно-фугасного снаряда, здесь крупный наружный корпус объединяет два отдельных внутренних изделия.',
    'Корпус изготовлен из кованой стали. В описанном заводском исполнении он оливковый, с жёлтой маркировкой. Полная масса со взрывателем составляет 47 кг, длина в той же комплектации — 898 мм. Эти характеристики относятся к целому снаряду, а не к одному его боевому элементу.',
    'В истории промышленного предложения SMArt 155 названы немецкая GIWS и американская General Dynamics Ordnance and Tactical Systems. По общему классу модель близка к BONUS, но это отдельная разработка. Исходная запись массы основного вещества содержит несогласованные фунты и килограммы; это расхождение обозначено в таблице, без выбора неподтверждённого точного значения.',
    evidence=[{'url':'https://www.gdots.com/wp-content/uploads/2017/11/SMArt155.pdf','claims':'Два самостоятельных внутренних боеприпаса, общий класс SFM, материал корпуса, окраска, длина и масса со взрывателем; промышленная кооперация GIWS/GD-OTS. Алгоритмы, дистанции, механизмы действия исключены.'}])
add('ref-v10-artillery-xm1113',
    'XM1113 — американский 155-мм активно-реактивный артиллерийский снаряд. Это самостоятельный класс ствольного боеприпаса: помимо основной артиллерийской части, его конструкция включает ракетный компонент. Такой признак отличает XM1113 от обычного осколочно-фугасного снаряда того же калибра.',
    'В материалах General Dynamics 2019–2020 годов XM1113 представлен как развитие линии, предназначенное для замены M549A1. Таким образом, история проекта связана с обновлением более ранней американской номенклатуры, а не просто с появлением другого названия для прежнего корпуса.',
    'В обзоре 2017 года изделие ещё описывалось как разработка. Позднейшее заводское обозначение сохраняет индекс XM1113. Исторический статус конкретной публикации не использован как утверждение о нынешнем состоянии всех поставок; точные масса и габариты в этой записи отдельно не установлены.',
    evidence=[{'url':'https://www.gd.com/Articles/2019/10/10/general-dynamics-at-ausa-2019','claims':'Класс Rocket Assisted Projectile, XM1113, связь с M549A1; историческое промышленное представление. Численные дальности исключены.'},{'url':'https://www.gd.com/Articles/2020/10/08/gd-at-ausa-2020','claims':'Официальный поисковый результат General Dynamics подтверждает описание разработки и связь с заменой M549A1; полный текст страницы недоступен, текущий статус не утверждается.'}])
add('ref-v10-artillery-xm1128',
    'XM1128 — американский 155-мм осколочно-фугасный артиллерийский снаряд с единым основным корпусом. Он относится к программам развития американских ствольных боеприпасов. Внутри этой номенклатуры XM1128 выделен отдельно от активно-реактивного XM1113 и кассетного M864.',
    'История проекта включает не только конструкторскую работу, но и подготовку промышленного производства. В 2019 году контракт по программе подготовки выпуска был заключён с American Ordnance на предприятии Iowa Army Ammunition Plant. Армия США описала эту работу в январе 2020 года.',
    'Такой промышленный контекст объясняет, почему ранние публикации говорят о разработке и создании производственных возможностей. Они описывают конкретный этап истории XM1128. Подтверждённые полная масса и наружная длина в имеющейся записи отсутствуют и не заменены значениями соседних 155-мм моделей.',
    evidence=[{'url':'https://www.army.mil/article/231418/new_cornerstone_ota_boosts_xm1128_development_and_the_industrial_base','claims':'155-мм HE unitary projectile; контракт American Ordnance 2019 года на Iowa Army Ammunition Plant; историческая стадия промышленной подготовки. Производственные методы и параметры применения исключены.'}])
add('ref-v10-artillery-lu211',
    'LU211 — французское семейство 155-мм осколочно-фугасных артиллерийских снарядов KNDS. Основное обозначение объединяет исполнения HE HB и HE BB. Дополнительные буквы относятся к конкретным вариантам, которые имеют собственные размеры и массу.',
    'Для HE HB приведены масса снаряда 42,5 кг и длина 865 мм; для HE BB — 43,9 кг и 867 мм. Наружный размер близок, но массы различаются. Это наглядный пример того, почему одно семейное название нельзя свести к единому числовому паспорту.',
    'Внутри описаний LU211 встречаются также разные варианты основного вещества, включая исполнение IM. Такие записи сохранены с собственными обозначениями. Общие цифры калибра и семейства позволяют сравнивать линию целиком, а полные суффиксы — различать отдельные изделия.')
add('ref-v10-artillery-lu215',
    'LU215 — французский 155-мм осветительный артиллерийский снаряд KNDS. Его основной класс связан с осветительным содержимым, а не с единым осколочно-фугасным зарядом. В этой линии используется полное обозначение LU215 ILL BB.',
    'Для описанного варианта BB приведены масса снаряда 43,7 кг и длина 898 мм. Это крупное артиллерийское изделие, которое по размеру может быть близко к другим 155-мм снарядам той же линейки, несмотря на иное назначение.',
    'Родственная номенклатура включает инфракрасный осветительный LU216 и дымовой LU217. Совпадение калибра и близкая наружная длина объединяют общую размерную группу, но не одинаковое содержимое. Характеристики LU215 ниже относятся к названному варианту BB.')
add('ref-v10-artillery-lu216',
    'LU216 — французский 155-мм инфракрасный осветительный артиллерийский снаряд KNDS. Полное обозначение LU216 IR-ILL BB показывает принадлежность к отдельной осветительной линии. Инфракрасная классификация отличает его от обычного осветительного LU215.',
    'Описанный вариант BB имеет массу снаряда 43,7 кг и длину 898 мм. Эти значения совпадают с приведёнными характеристиками LU215 BB, хотя основной осветительный состав относится к другому виду. Одинаковая масса поэтому не означает одно и то же изделие.',
    'Семейная номенклатура LU объединяет также осколочно-фугасные и дымовые модели. Для LU216 отдельно установлена масса основного осветительного содержимого 2,4 кг; она является характеристикой содержимого, а не полной массой снаряда. Точная марка состава здесь не раскрыта.')
add('ref-v10-artillery-lu217',
    'LU217 — французский 155-мм дымовой артиллерийский снаряд KNDS. Он принадлежит к той же широкой линейке LU, что и осколочно-фугасный LU211 и осветительные LU215 и LU216, но имеет самостоятельный дымовой класс. Полное обозначение описанного исполнения — LU217 SMK BB.',
    'Масса снаряда LU217 BB составляет 44,6 кг, длина — 898 мм. По наружному размеру он близок к осветительным моделям линии. Эта близость показывает, что одинаковый калибр и длина корпуса могут объединять боеприпасы с различным содержимым.',
    'Масса дымового содержимого приведена отдельно — 5 кг. Точная марка состава в этой записи не названа. Характеристики относятся к варианту BB; обозначения других дымовых снарядов не используются как второе имя LU217.')
add('ref-v10-artillery-m107-family',
    'M107 — американский 155-мм осколочно-фугасный артиллерийский снаряд, история которого продолжилась в зарубежном лицензионном производстве. Южнокорейская компания Poongsan выпускает связанную с ним модель KM107. Буква K сохраняет национальное обозначение внутри общей конструктивной линии.',
    'Для KM107 приведена масса снаряда 41,86 кг. Это характеристика южнокорейского изделия, а не универсальное значение для любого M107. В американской линии отдельно представлены исполнения с TNT и Composition B, имеющие собственные записи массы основного вещества.',
    'Семейная карточка позволяет увидеть связь исходной модели и лицензионной версии. При этом сведения о содержимом американского M107 не перенесены на KM107 без отдельного подтверждения. Общее происхождение конструкции и точная спецификация конкретного выпуска остаются разными уровнями описания.')
add('ref-v10-artillery-nm269',
    'NM269 — обозначение 155-мм осколочно-фугасного артиллерийского снаряда Nammo, известного также как IM HE-ER. Полный индекс объединяет конкретную модель и её классификацию внутри широкой артиллерийской номенклатуры изготовителя.',
    'Для NM269 приведена масса снаряда со взрывателем 44,4 кг. Основное вещество обозначено MCX-6100 IM, а его масса указана как более 10 кг. Знак «более» является частью подтверждённой характеристики: он не заменён точным числом для удобства сравнения.',
    'Nammo объединяет предприятия нескольких стран. Поэтому принадлежность к продукции группы сама по себе не устанавливает страну изготовления именно NM269. Внешние изображения с общей маркировкой IM HE-ER также следует отличать от подписанного изображения точной модели с индексом NM269.')
add('ref-v10-artillery-k122-kitolov-2m',
    'К122 — обозначение 122-мм управляемого артиллерийского снаряда «Китолов-2М». История модели связана с российским КБП. Название «Китолов-2М» относится к системе, тогда как индекс К122 выделяет сам снаряд в её составе.',
    'Длина снаряда составляет 1190 мм, а масса в одной записи — 28,3 кг. При небольшом сравнительно с 152-мм моделями калибре это заметно вытянутый предмет. В другой архивной таблице масса округлена до 28 кг; две записи ниже сохранены со своими определениями.',
    'Масса всей боевой части 12,25 кг и масса её основного заряда 5,3 кг описывают разные объекты. Ни одна из них не является полной массой К122. Такой раздельный учёт помогает понять масштаб частей снаряда, не смешивая индекс системы, целое изделие и его внутреннее содержимое.')
